import * as THREE from 'three/webgpu';
import * as tsl from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl:string}} assets
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Array<{name:string,trigger?:string,params?:Object}>} cinematicPrimitives
 * @property {Object} [id]
 */

/**
 * @typedef {Object} NodeContext
 * @property {THREE.TextureLoader} textureLoader
 * @property {Object<string,Function>} primitives
 * @property {Function} [emit]
 */

export default function createNode(config, ctx) {
  // -------------------------------------------------
  // Geometry & Textures
  // -------------------------------------------------
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  const colorTex = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTex = ctx.textureLoader.load(config.assets.depthMapUrl);

  // -------------------------------------------------
  // Material (TSL – node based)
  // -------------------------------------------------
  const material = new tsl.MeshPhysicalNodeMaterial();

  // Base color
  material.colorNode = tsl.texture(colorTex);
  // Displacement
  material.displacementNode = tsl.texture(depthTex);
  material.displacementScaleNode = tsl.float(0.2);

  // Machined‑metal PBR values
  material.metalness = 0.4;
  material.roughness = 0.6;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.1;

  // Slight accent rim (optional)
  material.emissiveNode = tsl.mix(
    tsl.float(0.0),
    tsl.vec3(1.0, 0.165, 0.22), // accent #ff2a38
    tsl.smoothstep(0.5, 1.0, tsl.dot(tsl.viewDirectionNode, tsl.normalNode))
  );

  // -------------------------------------------------
  // Mesh
  // -------------------------------------------------
  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  // Apply placement
  mesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  mesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  mesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // -------------------------------------------------
  // Cinematic Primitives
  // -------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params ?? {});
      }
    }
  }

  // -------------------------------------------------
  // Interaction Handlers
  // -------------------------------------------------
  const baseY = mesh.position.y;
  const hoverTweenKey = Symbol('hoverTween');

  const handlers = {};

  // Hover – rise‑in (subtle 0.15 units)
  handlers.hoverEnter = () => {
    const tl = gsap.to(mesh.position, {
      y: baseY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
    mesh.userData[hoverTweenKey] = tl;
  };
  handlers.hoverLeave = () => {
    const prev = mesh.userData[hoverTweenKey];
    if (prev) {
      prev.kill();
      delete mesh.userData[hoverTweenKey];
    }
    gsap.to(mesh.position, {
      y: baseY,
      duration: 0.15,
      ease: 'power3.out',
    });
  };

  // Click – emit navigation event
  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-home.select');
    }
  };

  mesh.userData.handlers = handlers;

  // -------------------------------------------------
  // Cleanup
  // -------------------------------------------------
  mesh.userData.cleanup = () => {
    // Stop any GSAP tweens
    const prev = mesh.userData[hoverTweenKey];
    if (prev) prev.kill();

    geometry.dispose();
    material.dispose();
    if (colorTex && colorTex.dispose) colorTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();
  };

  return mesh;
}
